def _solve(dose, ts):
    ts = np.asarray(ts, float)
    def f(t, y):
        A1, A2 = y
        C = A1 / V1
        cl = Vmax * C / (Km + C)
        dA1 = -cl - Q*(C - A2/V2)
        dA2 = Q*(C - A2/V2)
        return [dA1, dA2]
    sol = solve_ivp(f, (0, ts.max()), [dose, 0.0], t_eval=ts, rtol=1e-8, atol=1e-10, method='LSODA')
    return sol.y[0] / V1
def predict(df, p):
    global V1, Vmax, Km, Q, V2
    V1, Vmax, Km, Q, V2 = p['V1'], p['Vmax'], p['Km'], p['Q'], p['V2']
    def solve_one(dose, ts):
        return _solve(dose, ts)
    return per_dose(df, solve_one)

